import java.util.*; 
public class HaPicker {
    private final TreeMap<Long, String> ring = new TreeMap<>();
    private final Map<String, Integer> weights = new HashMap<>();
    private final Map<String, Integer> inflight = new HashMap<>();
    private final Set<String> healthy = new HashSet<>();
    private static final int VNODES = 160;
    public synchronized void addBackend(String addr, int weight) {
        weights.put(addr, weight);
        inflight.putIfAbsent(addr, 0);
        healthy.add(addr);
        for (int i = 0; i < VNODES; i++) {
            long h = hash(addr + "#" + i);
            ring.put(h, addr);
        }
    }
    public synchronized void setHealthy(String addr, boolean up) {
        if (up) healthy.add(addr); else healthy.remove(addr);
    }
    public synchronized String pickSticky(String flowKey) {
        if (ring.isEmpty()) return null;
        long h = hash(flowKey);
        for (int i = 0; i < ring.size(); i++) {
            Map.Entry<Long, String> e = ring.ceilingEntry(h);
            if (e == null) e = ring.firstEntry();
            String cand = e.getValue();
            h = e.getKey() + 1;
            if (healthy.contains(cand) && !overloaded(cand)) return cand;
        }
        return pickLeastConn();
    }
    public synchronized String pickLeastConn() {
        String best = null; double bestScore = Double.MAX_VALUE;
        for (String b : healthy) {
            double score = (double) inflight.getOrDefault(b, 0) / weights.getOrDefault(b, 1);
            if (score < bestScore) { bestScore = score; best = b; }
        }
        return best;
    }
    private boolean overloaded(String b) {
        int cap = weights.getOrDefault(b, 1) * 4;
        return inflight.getOrDefault(b, 0) >= cap;
    }
    public synchronized void acquired(String b) { inflight.merge(b, 1, Integer::sum); }
    public synchronized void released(String b) { inflight.merge(b, -1, Integer::sum); }
    private long hash(String s) {
        long h = 1125899906842597L;
        for (int i = 0; i < s.length(); i++) { h = 31 * h + s.charAt(i); }
        return h & Long.MAX_VALUE;
    }
}

import time, collections
FAIL_TO_EJECT = 2
OK_TO_REJOIN = 3
BACKOFF_BASE = 5
fails = collections.defaultdict(int)
oks = collections.defaultdict(int)
backoff_until = {}
def probe(addr):
    # tcp + /healthz + p99 sample; return (up: bool, latency_ms: float)
    raise NotImplementedError
def should_route(addr, now):
    return now >= backoff_until.get(addr, 0)
def loop(backends, eject, rejoin):
    while True:
        now = time.time()
        for b in backends:
            try:
                up, _ = probe(b)
            except Exception:
                up = False
            if up:
                fails[b] = 0
                oks[b] += 1
                if oks[b] >= OK_TO_REJOIN:
                    rejoin(b)
                    oks[b] = 0
            else:
                oks[b] = 0
                fails[b] += 1
                if fails[b] >= FAIL_TO_EJECT and should_route(b, now):
                    eject(b)
                    fails[b] = 0
                    # flap damping: doubling quarantine on repeated eject
                    prev = backoff_until.get(b, 0)
                    wait = BACKOFF_BASE if prev <= now else min(300, (prev - now) * 2)
                    backoff_until[b] = now + wait
        time.sleep(2)
